    public void run() throws Exception {
        if (!HASH.equals(currentProgram.getExecutableSHA256()) || currentProgram.getImageBase().getOffset() != 0x6f000000L)
            throw new Exception("Requires game.dll 1.27.1.7085 at preferred base 6f000000");
        // Validate the whole batch before touching existing annotations.
        for (String[] row : ROWS) {
            Function f = getFunctionAt(toAddr(row[0]));
            if (f == null) {
                // Verified native registration and complete decoded switch;
                // Ghidra initially had instructions but no function at2005b0.
                if (!(row[0].equals("6f002170") || row[0].equals("6f2005b0") || row[0].equals("6f001dd0") || row[0].equals("6f019880") || row[0].equals("6f001d50") ||
                      row[0].equals("6f001a80") || row[0].equals("6f001b80") || row[0].equals("6f001e70") || row[0].equals("6f0040d0") || row[0].equals("6f004180") || row[0].equals("6f004190") || row[0].matches("6f9b(8930|c0f0|8b50|88c0|9630|8a20)") || row[0].matches("6f0162(10|20|30|40|90|b0|c0|d0)")) || getInstructionAt(toAddr(row[0])) == null ||
                    getFunctionContaining(toAddr(row[0])) != null)
                    throw new Exception("Missing function " + row[0]);
                continue;
            }
            // Explicit migration of our earlier order/task misidentification.
            boolean taskCorrection =
                (row[0].equals("6f691260") && f.getName().equals("Unit_PopInternalOrderHead")) ||
                (row[0].equals("6f67df00") && f.getName().equals("Unit_DispatchInternalOrderQueue")) ||
                (row[0].equals("6f6927a0") && f.getName().equals("Unit_CreateAgentTask"));
            boolean requestCorrection =
                (row[0].equals("6f16dc50") && f.getName().equals("PathGroup_SetExtendedFlag2")) ||
                (row[0].equals("6f16dcb0") && f.getName().equals("PathGroup_SetExtendedFlag4")) ||
                (row[0].equals("6f16dc70") && f.getName().equals("PathGroup_SetExtendedFlag8"));
            if (!taskCorrection && !requestCorrection && f.getSymbol().getSource() != SourceType.DEFAULT && !f.getName().equals(row[1]) && !f.getName().startsWith("FUN_"))
                throw new Exception("Preserve existing annotation " + f.getName());
        }
        for (String[] row : ROWS) {
            Function f = getFunctionAt(toAddr(row[0]));
            if (f == null) f = createFunction(toAddr(row[0]), row[1]);
            if (f == null) throw new Exception("Cannot create verified native " + row[0]);
            f.setName(row[1], SourceType.USER_DEFINED);
            String evidence = row[2] + "\nRecovered descriptive name, not an original debug symbol. "
                + "See open-realm/docs/games/warcraft-3/retail-pathfinding.md. SHA256 " + HASH;
            String prior = f.getComment();
            if (prior == null || prior.isEmpty()) f.setComment(evidence);
            else if (!prior.contains(row[2])) f.setComment(prior + "\n" + evidence);
        }
        String[][] evidenceLabels = {
            {"6f68a8fb", "UnitCreation_AfterOptionalMoveOwner"},
            {"6f68a8de", "UnitCreation_CreateNonzeroSpeedMoveOwner"},
            {"6f68a8c4", "UnitCreation_TestCapturedMoveSpeed"},
            {"6fce6000", "UnitMovementType_NameTable"},
            {"6f68836e", "UnitRemoval_TargetLostPublication"},
            {"6fd541bc", "PathFormation_DefaultRankGap"},
            {"6fd541c8", "PathFormation_AlternateRankGap"},
            {"6fd541c4", "PathFormation_DefaultDepthPadding"},
            {"6fd541d0", "PathFormation_AlternateDepthPadding"}
        };
        for (String[] label : evidenceLabels)
            createLabel(toAddr(label[0]), label[1], true, SourceType.USER_DEFINED);
        println("Mapped " + ROWS.length + " evidence-backed pathfinding functions; prototypes unchanged.");
    }
